//! Fixed differential-test driver for the libexpat port. Owned by the
//! harness (role C). Argon replaces only `src/expat.rs`; do not edit this file.
//!
//! Mirrors backend/harness/expat/drivers/expat_driver.c byte for byte:
//!   Ok(events)  -> one line per event, then `OK\n`
//!   Err(e)      -> only `ERROR <code> line <line> col <col>\n`
//! Always exits 0 unless the process panics.
#![forbid(unsafe_code)]

mod expat;

use expat::Event;
use std::io::{self, Read, Write};

/// Quoted string: bytes 0x20..=0x7E as themselves except `"` and `\`
/// (printed as `\"` and `\\`); every other byte as `\xNN`, lowercase hex.
fn quoted(out: &mut Vec<u8>, s: &[u8]) {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    out.push(b'"');
    for &c in s {
        if c == b'"' || c == b'\\' {
            out.push(b'\\');
            out.push(c);
        } else if (0x20..=0x7e).contains(&c) {
            out.push(c);
        } else {
            out.extend_from_slice(b"\\x");
            out.push(HEX[(c >> 4) as usize]);
            out.push(HEX[(c & 15) as usize]);
        }
    }
    out.push(b'"');
}

/// A string expat may pass as NULL: `null` or a quoted string.
fn opt(out: &mut Vec<u8>, s: &Option<Vec<u8>>) {
    match s {
        Some(v) => quoted(out, v),
        None => out.extend_from_slice(b"null"),
    }
}

fn flag(b: bool) -> &'static [u8] {
    if b {
        b"1"
    } else {
        b"0"
    }
}

fn write_event(out: &mut Vec<u8>, ev: &Event) {
    match ev {
        Event::XmlDecl { version, encoding, standalone } => {
            out.extend_from_slice(b"XMLDECL ");
            opt(out, version);
            out.push(b' ');
            opt(out, encoding);
            out.extend_from_slice(format!(" {}", standalone).as_bytes());
        }
        Event::DoctypeStart { name, sysid, pubid, has_internal_subset } => {
            out.extend_from_slice(b"DOCTYPE_START ");
            quoted(out, name);
            out.push(b' ');
            opt(out, sysid);
            out.push(b' ');
            opt(out, pubid);
            out.push(b' ');
            out.extend_from_slice(flag(*has_internal_subset));
        }
        Event::DoctypeEnd => out.extend_from_slice(b"DOCTYPE_END"),
        Event::EntityDecl { name, is_pe, value, sysid, pubid, notation } => {
            out.extend_from_slice(b"ENTITY ");
            quoted(out, name);
            out.push(b' ');
            out.extend_from_slice(flag(*is_pe));
            match value {
                Some(v) => {
                    out.extend_from_slice(b" VALUE ");
                    quoted(out, v);
                }
                None => {
                    out.extend_from_slice(b" EXTERNAL ");
                    opt(out, sysid);
                    out.push(b' ');
                    opt(out, pubid);
                    out.push(b' ');
                    opt(out, notation);
                }
            }
        }
        Event::Start { name, attrs } => {
            out.extend_from_slice(b"START ");
            quoted(out, name);
            for (k, v) in attrs {
                out.push(b' ');
                quoted(out, k);
                out.push(b'=');
                quoted(out, v);
            }
        }
        Event::End { name } => {
            out.extend_from_slice(b"END ");
            quoted(out, name);
        }
        Event::Text(t) => {
            out.extend_from_slice(b"TEXT ");
            quoted(out, t);
        }
        Event::Pi { target, data } => {
            out.extend_from_slice(b"PI ");
            quoted(out, target);
            out.push(b' ');
            quoted(out, data);
        }
        Event::Comment(c) => {
            out.extend_from_slice(b"COMMENT ");
            quoted(out, c);
        }
        Event::CdataStart => out.extend_from_slice(b"CDATA_START"),
        Event::CdataEnd => out.extend_from_slice(b"CDATA_END"),
        Event::Skipped { name, is_pe } => {
            out.extend_from_slice(b"SKIPPED ");
            quoted(out, name);
            out.push(b' ');
            out.extend_from_slice(flag(*is_pe));
        }
    }
    out.push(b'\n');
}

fn main() {
    let mut input = Vec::new();
    if io::stdin().lock().read_to_end(&mut input).is_err() {
        eprintln!("driver: failed to read stdin");
        std::process::exit(2);
    }

    let mut out: Vec<u8> = Vec::new();
    match expat::parse(&input) {
        Ok(events) => {
            // The C driver coalesces adjacent character data into one TEXT
            // line. Do the same here so expat.rs may emit text in any chunks.
            let mut pending: Option<Vec<u8>> = None;
            for ev in &events {
                if let Event::Text(t) = ev {
                    if t.is_empty() {
                        continue; // C ignores empty runs too
                    }
                    pending.get_or_insert_with(Vec::new).extend_from_slice(t);
                    continue;
                }
                if let Some(t) = pending.take() {
                    write_event(&mut out, &Event::Text(t));
                }
                write_event(&mut out, ev);
            }
            if let Some(t) = pending.take() {
                write_event(&mut out, &Event::Text(t));
            }
            out.extend_from_slice(b"OK\n");
        }
        Err(e) => {
            out.extend_from_slice(format!("ERROR {} line {} col {}\n", e.code, e.line, e.col).as_bytes());
        }
    }

    let mut stdout = io::stdout().lock();
    let _ = stdout.write_all(&out);
    let _ = stdout.flush();
}
